let S;try{S=JSON.parse(localStorage.getItem(K))||seed()}catch{S=seed()}S.profile={...seed().profile,...S.profile};S.settings={...seed().settings,...S.settings};S.activities=Array.isArray(S.activities)?S.activities:[];S.tasks=Array.isArray(S.tasks)?S.tasks:[];S.routines=Array.isArray(S.routines)?S.routines:[];S.routineSkips=Array.isArray(S.routineSkips)?S.routineSkips:[];S.attendance=Array.isArray(S.attendance)?S.attendance:[];S.goals=Array.isArray(S.goals)?S.goals:[];S.projects=Array.isArray(S.projects)?S.projects:[];S.finance=Array.isArray(S.finance)?S.finance:[];S.budgets=Array.isArray(S.budgets)?S.budgets:[];S.investments=Array.isArray(S.investments)?S.investments:[];S.financeGoals=Array.isArray(S.financeGoals)?S.financeGoals:[];S.recurringFinance=Array.isArray(S.recurringFinance)?S.recurringFinance:[];S.debts=Array.isArray(S.debts)?S.debts:[];S.netWorthSnapshots=Array.isArray(S.netWorthSnapshots)?S.netWorthSnapshots:[];S.healthLogs=Array.isArray(S.healthLogs)?S.healthLogs:[];S.reminderLog=Array.isArray(S.reminderLog)?S.reminderLog:[];S.notes=Array.isArray(S.notes)?S.notes:[];S.journal=S.journal||{};S.meta={version:5,activeTimer:null,...(S.meta||{})};S.tasks=S.tasks.map(t=>({...t,status:t.status==='todo'?'planned':(t.status||'planned'),subtasks:Array.isArray(t.subtasks)?t.subtasks:[],tags:Array.isArray(t.tags)?t.tags:[],recurrence:t.recurrence||'none'}));
