function activityXP(a){const d=clamp(+a.duration||0,1,480),w=XP_WEIGHT[a.category]||1;let bonus=a.source==='pomodoro'&&a.completed!==false?12:0;if(a.source==='routine')bonus+=4;if(a.obligation==='mandatory')bonus+=5;if(a.goalId)bonus+=8;return Math.max(1,Math.round(d*w+bonus))}
function task(x){const pct=taskProgress(x),sub=(x.subtasks||[]),over=x.deadline&&x.deadline<today()&&x.status!=='done';return'<div class="task-item task-rich '+(x.status==='done'?'task-complete':'')+'"><button class="check '+(x.status==='done'?'done':'')+'" data-act="toggle" data-id="'+x.id+'">'+(x.status==='done'?'✓':'')+'</button><div class="item-main"><div class="task-title-row"><div class="item-title '+(x.status==='done'?'done':'')+'">'+esc(x.title)+'</div><span class="pill task-status '+(x.status||'planned')+'">'+esc(x.status||'planned')+'</span></div><div class="item-meta"><span>'+cat(x.category)+'</span><span>• '+mins(x.estimate)+'</span>'+(x.startTime?'<span>• '+esc(x.startTime)+'</span>':'')+(x.deadline?'<span class="'+(over?'overdue-text':'')+'">• deadline '+fmt(x.deadline,{day:'numeric',month:'short'})+'</span>':'')+(x.goalId?'<span>• '+esc(goal(x.goalId))+'</span>':'')+'<span class="pill '+(x.priority==='high'?'red':x.priority==='medium'?'orange':'')+'">'+x.priority+'</span>'+(x.recurrence&&x.recurrence!=='none'?'<span class="pill blue">↻ '+x.recurrence+'</span>':'')+'<span class="xp-pop">+'+taskXP(x)+' XP</span></div>'+(sub.length?'<div class="task-subprogress">'+prog(pct)+'<small>'+sub.filter(s=>s.done).length+'/'+sub.length+' subtask</small></div>':'')+((x.tags||[]).length?'<div class="task-tags">'+x.tags.map(t=>'<span>#'+esc(t)+'</span>').join('')+'</div>':'')+'</div><div class="task-actions">'+(x.status!=='done'?'<button class="mini-btn task-start" data-act="startTaskTimer" data-id="'+x.id+'">▶ Start</button>':'')+'<button class="mini-btn" data-act="editTask" data-id="'+x.id+'">Edit</button></div></div>'}
function weekday(d=today()){return new Date(d+'T12:00:00').getDay()}
function routineDue(r,d=today()){return r.active!==false&&Array.isArray(r.days)&&r.days.map(Number).includes(weekday(d))}
function dueRoutines(d=today()){return S.routines.filter(r=>routineDue(r,d)).sort((a,b)=>(a.time||'23:59').localeCompare(b.time||'23:59'))}
function routineActivity(r,d=today()){return S.activities.find(a=>a.routineId===r.id&&a.date===d&&a.completed!==false)||null}
function routineSkip(r,d=today()){return S.routineSkips.find(x=>x.routineId===r.id&&x.date===d)||null}
function routineState(r,d=today()){if(routineActivity(r,d))return'completed';if(routineSkip(r,d))return'skipped';if(d<today())return'missed';if(d>today())return'upcoming';return (r.time&&localTime()>r.time)?'overdue':'pending'}
function completeRoutine(id,d=today()){const r=S.routines.find(x=>x.id===id);if(!r||routineActivity(r,d))return;S.routineSkips=S.routineSkips.filter(x=>!(x.routineId===id&&x.date===d));const a={id:uid('a'),date:d,startTime:d===today()?localTime():(r.time||'00:00'),plannedTime:r.time||null,title:r.title,category:r.category||'personal',duration:Math.max(1,+r.duration||30),goalId:r.goalId||null,source:'routine',completed:true,routineId:r.id,rhythm:'routine',obligation:r.obligation||'important',planned:true,notes:''};S.activities.push(a);save();toast(r.title+' selesai · +'+activityXP(a)+' XP');render()}
function skipRoutine(id,d=today()){const r=S.routines.find(x=>x.id===id);if(!r||routineActivity(r,d)||routineSkip(r,d))return;if(r.obligation==='mandatory'&&!confirm('Tandai kegiatan wajib ini sebagai dilewati?'))return;S.routineSkips.push({id:uid('skip'),routineId:id,date:d,time:d===today()?localTime():null,obligation:r.obligation||'important'});save();toast('Dicatat sebagai dilewati');render()}
function routineCompletion(d=today()){const due=dueRoutines(d);if(!due.length)return{due:0,done:0,mandatory:0,mandatoryDone:0,pct:0};const done=due.filter(r=>routineActivity(r,d)).length,mandatory=due.filter(r=>r.obligation==='mandatory').length,mandatoryDone=due.filter(r=>r.obligation==='mandatory'&&routineActivity(r,d)).length;return{due:due.length,done,mandatory,mandatoryDone,pct:Math.round(done/due.length*100)}}
function routineAdherence(days=30){let due=0,done=0,mandatoryDue=0,mandatoryDone=0;for(let i=0;i<days;i++){const d=add(today(),-i);for(const r of dueRoutines(d)){due++;if(routineActivity(r,d))done++;if(r.obligation==='mandatory'){mandatoryDue++;if(routineActivity(r,d))mandatoryDone++}}}return{due,done,pct:due?Math.round(done/due*100):0,mandatoryPct:mandatoryDue?Math.round(mandatoryDone/mandatoryDue*100):0}}
function spontaneousActivities(d=today()){return S.activities.filter(a=>a.date===d&&a.planned===false)}
function lifeTime(d=today()){return S.activities.filter(a=>a.date===d).reduce((n,a)=>n+(+a.duration||0),0)}
function routineRow(r,d=today()){const st=routineState(r,d),done=st==='completed',skipped=st==='skipped',late=st==='overdue'||st==='missed';return'<div class="routine-row '+st+'"><div class="routine-time">'+esc(r.time||'Fleksibel')+'</div><div class="routine-main"><div class="routine-title">'+esc(r.title)+'</div><div class="routine-meta"><span>'+cat(r.category)+'</span><span class="pill '+(r.obligation==='mandatory'?'red':r.obligation==='important'?'orange':'')+'">'+(OBLIGATION_LABEL[r.obligation]||'Penting')+'</span><span>'+mins(r.duration)+'</span>'+(late?'<span class="routine-alert">Terlambat</span>':'')+'</div></div><div class="routine-actions">'+(done?'<span class="routine-done">✓ Selesai</span>':skipped?'<span class="routine-skipped">Dilewati</span>':'<button class="mini-btn routine-complete" data-act="completeRoutine" data-id="'+r.id+'">✓ Done</button><button class="mini-btn" data-act="skipRoutine" data-id="'+r.id+'">Skip</button>')+'</div></div>'}
function todayLifeCard(){const due=dueRoutines(),rc=routineCompletion();return'<article class="card life-today-card"><div class="card-head"><div><h2>Life Plan Hari Ini</h2><p>'+rc.done+'/'+rc.due+' kegiatan rutin selesai.</p></div><button class="btn btn-ghost" data-route="life">Buka Life Log →</button></div><div class="routine-list">'+(due.length?due.slice(0,6).map(r=>routineRow(r)).join(''):'<div class="empty empty-compact">Belum ada rutinitas untuk hari ini.</div>')+'</div>'+(due.length>6?'<div class="item-meta" style="margin-top:9px">+'+(due.length-6)+' kegiatan lainnya</div>':'')+'</article>'}
