const xp=()=>S.activities.reduce((a,x)=>a+activityXP(x),0)+S.tasks.filter(x=>x.status==='done').reduce((a,x)=>a+taskXP(x),0)+S.attendance.length*15,level=()=>({level:Math.floor(xp()/1200)+1,cur:xp()%1200,pct:Math.round((xp()%1200)/12)});

