function calDate(y,m,d){return new Date(Date.UTC(y,m,d)).toISOString().slice(0,10)}
function calMonthLabel(){return new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(calendarCursor.year,calendarCursor.month,1)))}
function calendarItems(d){const tasks=S.tasks.filter(t=>!t.inbox&&t.date===d).map(t=>({kind:'task',id:t.id,date:d,title:t.title,time:t.startTime||'',duration:+t.estimate||0,category:t.category||'personal',status:t.status==='done'?'done':'pending',priority:t.priority||'medium',deadline:t.deadline||'',draggable:true}));const routines=dueRoutines(d).map(r=>({kind:'routine',id:r.id,date:d,title:r.title,time:r.time||'',duration:+r.duration||0,category:r.category||'personal',status:routineActivity(r,d)?'done':routineSkip(r,d)?'skipped':'pending',priority:r.obligation||'important',draggable:false}));return tasks.concat(routines).sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'))}
function calendarEventDetail(kind,id,d){if(kind==='task'){const t=S.tasks.find(x=>x.id===id);if(!t)return;const done=t.status==='done',earned=taskXP(t);open('<div class="modal-head"><div><div class="eyebrow">CALENDAR EVENT</div><h2 id="modalTitle">'+esc(t.title)+'</h2></div><button class="icon-btn" data-act="close">×</button></div><div class="event-detail"><div class="event-detail-time"><span>▦</span><div><b>'+fmt(t.date,{weekday:'long',day:'numeric',month:'long',year:'numeric'})+'</b><small>'+(t.startTime?esc(t.startTime)+' • ':'')+mins(t.estimate||0)+'</small></div></div><div class="event-detail-grid"><div><span>Kategori</span><b>'+cat(t.category)+'</b></div><div><span>Prioritas</span><b>'+esc(t.priority||'medium')+'</b></div><div><span>Goal</span><b>'+esc(goal(t.goalId)||'—')+'</b></div><div><span>Status</span><b>'+(done?'Selesai':'Belum selesai')+'</b></div></div>'+(t.notes?'<div class="event-notes">'+esc(t.notes)+'</div>':'')+'<div class="event-xp">+'+earned+' XP ketika selesai</div><div class="event-actions">'+(!done?'<button class="btn btn-primary" data-act="completeCalendar" data-kind="task" data-id="'+t.id+'" data-date="'+d+'">✓ Tandai Selesai</button>':'<span class="event-completed">✓ Sudah selesai • +'+earned+' XP</span>')+'<button class="btn btn-secondary" data-act="editTask" data-id="'+t.id+'">Edit</button></div></div>');return}const r=S.routines.find(x=>x.id===id);if(!r)return;const a=routineActivity(r,d),done=!!a,earned=a?activityXP(a):activityXP({duration:r.duration,category:r.category,source:'routine',obligation:r.obligation,goalId:r.goalId});open('<div class="modal-head"><div><div class="eyebrow">ROUTINE EVENT</div><h2 id="modalTitle">'+esc(r.title)+'</h2></div><button class="icon-btn" data-act="close">×</button></div><div class="event-detail"><div class="event-detail-time"><span>↻</span><div><b>'+fmt(d,{weekday:'long',day:'numeric',month:'long',year:'numeric'})+'</b><small>'+(r.time?esc(r.time)+' • ':'')+mins(r.duration||0)+'</small></div></div><div class="event-detail-grid"><div><span>Kategori</span><b>'+cat(r.category)+'</b></div><div><span>Sifat</span><b>'+(OBLIGATION_LABEL[r.obligation]||'Penting')+'</b></div><div><span>Goal</span><b>'+esc(goal(r.goalId)||'—')+'</b></div><div><span>Status</span><b>'+(done?'Selesai':routineSkip(r,d)?'Dilewati':'Belum selesai')+'</b></div></div><div class="event-xp">+'+earned+' XP ketika selesai</div><div class="event-actions">'+(!done&&!routineSkip(r,d)?'<button class="btn btn-primary" data-act="completeCalendar" data-kind="routine" data-id="'+r.id+'" data-date="'+d+'">✓ Tandai Selesai</button>':done?'<span class="event-completed">✓ Sudah selesai • +'+earned+' XP</span>':'<span class="pill">Dilewati</span>')+'<button class="btn btn-secondary" data-act="editRoutine" data-id="'+r.id+'">Edit Routine</button></div></div>')}
function completeCalendar(kind,id,d){close();if(kind==='task'){const t=S.tasks.find(x=>x.id===id);if(t&&t.status!=='done'){t.status='done';save();toast(t.title+' selesai · +'+taskXP(t)+' XP');render()}}else completeRoutine(id,d)}
function dateShift(d,days){return add(d,days)}
function weekStartDate(d){const x=new Date(d+'T12:00:00'),n=x.getDay();x.setDate(x.getDate()-n);return iso(x)}
function calendarTitle(){if(calendarView==='month')return calMonthLabel();if(calendarView==='week'){const s=weekStartDate(calendarAnchor),e=add(s,6);return fmt(s,{day:'numeric',month:'short'})+' – '+fmt(e,{day:'numeric',month:'short',year:'numeric'})}return fmt(calendarAnchor,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}
function calendarToolbar(){return'<div class="month-toolbar calendar-toolbar"><div class="month-nav"><button class="icon-btn" data-act="calendarPrev">‹</button><button class="btn btn-secondary" data-act="calendarToday">Hari ini</button><button class="icon-btn" data-act="calendarNext">›</button></div><h2>'+esc(calendarTitle())+'</h2><div class="calendar-view-tabs">'+['month','week','day'].map(v=>'<button class="calendar-view-btn '+(calendarView===v?'active':'')+'" data-act="calendarView" data-view="'+v+'">'+({month:'Bulan',week:'Minggu',day:'Hari'}[v])+'</button>').join('')+'</div></div>'}
function calendarEventButton(ev,d,compact=false){return'<button class="calendar-event '+(compact?'compact ':'')+(ev.status==='done'?'done':ev.status==='skipped'?'skipped':'')+'" data-act="calendarEvent" data-kind="'+ev.kind+'" data-id="'+ev.id+'" data-date="'+d+'" '+(ev.draggable?'draggable="true" data-drag-task="'+ev.id+'"':'')+' title="'+esc((ev.time?ev.time+' ':'')+ev.title)+'"><span class="event-dot"></span>'+(ev.time?'<time>'+esc(ev.time)+'</time>':'')+'<b>'+esc(ev.title)+'</b>'+(ev.status==='done'?'<span class="event-check">✓</span>':'')+'</button>'}
function calendarMonthView(){const y=calendarCursor.year,m=calendarCursor.month,first=new Date(Date.UTC(y,m,1)).getUTCDay(),daysIn=new Date(Date.UTC(y,m+1,0)).getUTCDate(),prevDays=new Date(Date.UTC(y,m,0)).getUTCDate(),cells=[];for(let i=0;i<42;i++){let day=i-first+1,cy=y,cm=m,inMonth=true;if(day<1){day=prevDays+day;cm=m-1;if(cm<0){cm=11;cy--}inMonth=false}else if(day>daysIn){day-=daysIn;cm=m+1;if(cm>11){cm=0;cy++}inMonth=false}const d=calDate(cy,cm,day),items=calendarItems(d),isToday=d===today();cells.push('<div class="month-cell '+(inMonth?'':'outside')+' '+(isToday?'today':'')+'" data-drop-date="'+d+'"><button class="month-day-number" data-act="calendarOpenDay" data-date="'+d+'">'+day+'</button><div class="month-events">'+items.slice(0,4).map(ev=>calendarEventButton(ev,d,true)).join('')+(items.length>4?'<button class="calendar-more" data-act="calendarDay" data-date="'+d+'">+'+(items.length-4)+' lainnya</button>':'')+'</div></div>')}return'<div class="month-weekdays">'+['Min','Sen','Sel','Rab','Kam','Jum','Sab'].map(x=>'<div>'+x+'</div>').join('')+'</div><div class="month-grid">'+cells.join('')+'</div>'}
function calendarWeekView(){const s=weekStartDate(calendarAnchor),ds=Array.from({length:7},(_,i)=>add(s,i));return'<div class="week-calendar"><div class="week-calendar-head">'+ds.map(d=>'<button class="week-day-head '+(d===today()?'today':'')+'" data-act="calendarOpenDay" data-date="'+d+'"><span>'+fmt(d,{weekday:'short'})+'</span><b>'+fmt(d,{day:'numeric'})+'</b></button>').join('')+'</div><div class="week-calendar-grid">'+ds.map(d=>{const items=calendarItems(d);return'<div class="week-day-col '+(d===today()?'today':'')+'" data-drop-date="'+d+'"><button class="week-add" data-act="newTaskOnDate" data-date="'+d+'">+ Tambah</button><div class="week-events">'+(items.length?items.map(ev=>'<div class="week-event-wrap">'+calendarEventButton(ev,d)+'</div>').join(''):'<div class="week-empty">Kosong</div>')+'</div></div>'}).join('')+'</div></div>'}
function calendarDayView(){const d=calendarAnchor,items=calendarItems(d),hours=Array.from({length:17},(_,i)=>i+6);return'<div class="day-calendar" data-drop-date="'+d+'"><div class="day-calendar-head"><div><span class="eyebrow">DAY PLAN</span><h3>'+fmt(d,{weekday:'long',day:'numeric',month:'long'})+'</h3></div><button class="btn btn-primary" data-act="newTaskOnDate" data-date="'+d+'">+ Kegiatan</button></div><div class="day-time-grid">'+hours.map(h=>{const at=items.filter(x=>parseInt((x.time||'99').slice(0,2),10)===h);return'<div class="day-hour-row"><time>'+String(h).padStart(2,'0')+':00</time><div class="day-hour-slot">'+at.map(ev=>calendarEventButton(ev,d)).join('')+'</div></div>'}).join('')+'<div class="day-unscheduled">'+items.filter(x=>!x.time).map(ev=>calendarEventButton(ev,d)).join('')+'</div></div></div>'}
function calendarPage(){S.settings.calendarView=calendarView;save();const body=calendarView==='week'?calendarWeekView():calendarView==='day'?calendarDayView():calendarMonthView();$('#page').innerHTML=head('Calendar','Month untuk overview, Week untuk planning, Day untuk eksekusi. Drag task ke tanggal lain untuk menjadwalkan ulang.','<button class="btn btn-primary" data-act="addTask">+ Kegiatan</button>')+'<article class="card month-calendar-card">'+calendarToolbar()+body+'</article>'}
function settingsPage(){const notif=notificationSupported()?Notification.permission:'unsupported',cloud=cloudSession?.user?.email||null;$('#page').innerHTML=head('Settings','Atur target, timer, notification, cloud sync, dan data.')+'<div class="grid two-col"><article class="card"><div class="card-head"><h2>Profile & Targets</h2></div><div class="form-grid"><div class="field"><label>Nama</label><input id="sn" value="'+esc(S.profile.name)+'"></div><div class="field"><label>Daily target (menit)</label><input id="sd" type="number" min="1" value="'+S.profile.dailyFocusTarget+'"></div><div class="field"><label>Weekly target (menit)</label><input id="sw" type="number" min="1" value="'+S.profile.weeklyTarget+'"></div><div class="field"><label>Planner mulai</label><input id="splanstart" type="time" value="'+S.settings.plannerStart+'"></div><div class="field"><label>Planner selesai</label><input id="splanend" type="time" value="'+S.settings.plannerEnd+'"></div></div><button class="btn btn-primary" style="margin-top:12px" data-act="saveSettings">Simpan</button></article><article class="card"><div class="card-head"><div><h2>Pomodoro Engine</h2><p>Preset dapat dipilih langsung dari Today.</p></div><span class="pill blue">'+S.settings.pomodoroPreset+'</span></div><div class="form-grid"><div class="field"><label>Focus (menit)</label><input id="spf" type="number" min="5" max="180" value="'+S.settings.pomodoroFocus+'"></div><div class="field"><label>Short break</label><input id="sps" type="number" min="1" max="60" value="'+S.settings.pomodoroShortBreak+'"></div><div class="field"><label>Long break</label><input id="spl" type="number" min="1" max="90" value="'+S.settings.pomodoroLongBreak+'"></div><div class="field"><label>Sesi sebelum long break</label><input id="spc" type="number" min="1" max="12" value="'+S.settings.pomodoroCycles+'"></div></div></article><article class="card"><div class="card-head"><div><h2>Notifications & Reminders</h2><p>Reminder saat app terbuka; background push penuh butuh layanan push server.</p></div><span class="pill '+(notif==='granted'?'green':'orange')+'">'+esc(notif)+'</span></div><div class="field"><label>Reminder lead (menit)</label><input id="slead" type="number" min="0" max="180" value="'+S.settings.reminderLead+'"></div><button class="btn btn-primary" style="margin-top:12px" data-act="requestNotifications">'+(notif==='granted'?'Notification Aktif':'Aktifkan Notification')+'</button></article><article class="card"><div class="card-head"><div><h2>Cloud Sync (Supabase)</h2><p>Opsional. Local-first tetap bekerja tanpa cloud.</p></div><span class="pill '+(cloud?'green':'')+'">'+(cloud?'SIGNED IN':'LOCAL')+'</span></div><div class="form-grid"><div class="field full"><label>Supabase Project URL</label><input id="ssupaurl" value="'+esc(S.settings.supabaseUrl||'')+'" placeholder="https://xxxx.supabase.co"></div><div class="field full"><label>Supabase anon/publishable key</label><input id="ssupakey" value="'+esc(S.settings.supabaseAnonKey||'')+'" placeholder="Public anon key"></div></div><div class="cloud-auth-box">'+(cloud?'<div class="callout">Login sebagai <b>'+esc(cloud)+'</b>.</div><div class="button-row"><button class="btn btn-primary" data-act="cloudSave">Upload State</button><button class="btn btn-secondary" data-act="cloudLoad">Download State</button><button class="btn btn-ghost" data-act="cloudLogout">Logout</button></div>':'<div class="form-grid"><div class="field"><label>Email</label><input id="cloudEmail" type="email"></div><div class="field"><label>Password</label><input id="cloudPassword" type="password"></div></div><div class="button-row"><button class="btn btn-primary" data-act="cloudLogin">Login</button><button class="btn btn-secondary" data-act="cloudSignup">Sign Up</button></div>')+'</div><div class="callout" style="margin-top:12px">Butuh tabel <b>desca_state</b> + RLS pada project Supabase. Service-role key tidak boleh dimasukkan ke browser.</div></article><article class="card"><div class="card-head"><h2>Automatic XP</h2></div><div class="simple-list"><div class="list-row"><div class="item-main"><div class="item-title">Activity XP</div><div class="item-meta">Durasi × kategori + bonus sumber/goal.</div></div></div><div class="list-row"><div class="item-main"><div class="item-title">Task XP</div><div class="item-meta">Estimasi × prioritas, hanya saat selesai.</div></div></div></div></article><article class="card"><div class="card-head"><h2>Data & Privacy</h2></div><div class="callout">Secara default data tetap local-first di browser. Cloud hanya aktif jika kamu konfigurasikan sendiri.</div><div class="simple-list" style="margin-top:12px"><button class="btn btn-secondary" data-act="theme">Toggle dark mode</button><button class="btn btn-secondary" data-act="export">Export JSON</button><button class="btn btn-secondary" data-act="resetData">Reset semua data</button></div></article></div>'}
function render(){nav();side();let pb=$('.profile-chip b');if(pb)pb.textContent=S.profile.name||'Desca';document.documentElement.dataset.theme=S.settings.theme;document.body.classList.toggle('collapsed',!!S.settings.sidebarCollapsed);$('#themeToggle').textContent=S.settings.theme==='dark'?'☀':'☾';({today:todayPage,inbox:inboxPage,tasks:tasksPage,calendar:calendarPage,life:lifePage,progress:progressPage,goals:goalsPage,study:studyPage,research:()=>domain('research','Research','Catat jam riset dan kemajuan penulisan.'),projects:projectsPage,health:healthPage,finance:financePage,journal:journalPage,analytics:analyticsPage,reviews:reviewPage,achievements:achievementsPage,settings:settingsPage}[route]||todayPage)();updateFocusOverlay()}
function open(html){$('#modal').innerHTML=html;$('#modalBackdrop').hidden=false;document.body.classList.add('modal-open');requestAnimationFrame(()=>$('#modal input:not([disabled]),#modal textarea,#modal select')?.focus())}
function close(){$('#modalBackdrop').hidden=true;$('#modal').innerHTML='';document.body.classList.remove('modal-open')}
function searchItems(q=''){const s=q.trim().toLowerCase();if(!s)return[];let out=[];for(const t of S.tasks)if((t.title||'').toLowerCase().includes(s))out.push({type:'Task',title:t.title,meta:(t.date||'Inbox')+' • '+cat(t.category),route:'tasks'});for(const r of S.routines)if((r.title||'').toLowerCase().includes(s))out.push({type:'Routine',title:r.title,meta:(r.time||'Fleksibel')+' • '+cat(r.category),route:'life'});for(const a of S.activities)if((a.title||'').toLowerCase().includes(s))out.push({type:'Activity',title:a.title,meta:a.date+' • '+cat(a.category)+' • '+mins(a.duration),route:a.category==='study'?'study':a.category==='research'?'research':a.category==='health'?'health':'progress'});for(const g of S.goals)if((g.title||'').toLowerCase().includes(s))out.push({type:'Goal',title:g.title,meta:(g.area||'Goal')+' • '+(g.progress||0)+'%',route:'goals'});for(const n of S.notes)if((n.text||'').toLowerCase().includes(s))out.push({type:'Note',title:n.text.slice(0,90),meta:n.date,route:'inbox'});for(const [d,j] of Object.entries(S.journal))if(Object.values(j||{}).join(' ').toLowerCase().includes(s))out.push({type:'Journal',title:(j.l||j.a||j.t||'Journal entry').slice(0,90),meta:d,route:'journal'});return out.slice(0,18)}
function searchResults(q){const a=searchItems(q);return a.length?a.map(x=>'<button class="search-result" data-act="searchGo" data-route-target="'+x.route+'"><span class="search-type">'+x.type+'</span><span class="search-result-copy"><b>'+esc(x.title)+'</b><small>'+esc(x.meta)+'</small></span><span class="search-arrow">→</span></button>').join(''):'<div class="empty empty-compact"><span class="empty-icon">⌕</span><b>Tidak ada hasil</b><small>Coba kata kunci lain.</small></div>'}
function openSearch(){open('<div class="modal-head"><div><div class="eyebrow">Global Search</div><h2 id="modalTitle">Cari di Desca OS</h2></div><button class="icon-btn" data-act="close">×</button></div><div class="search-modal-box"><span>⌕</span><input id="globalSearchInput" autocomplete="off" placeholder="Cari task, activity, goal, note, journal..."><kbd>Esc</kbd></div><div id="searchResults" class="search-results"><div class="search-hint">Mulai mengetik untuk mencari seluruh workspace.</div></div>')}
function goalForm(g={}){const ms=(g.milestones||[]).join('\n');return'<form id="goalForm"><div class="form-grid"><div class="field full"><label>Nama goal</label><input name="title" required value="'+esc(g.title||'')+'" placeholder="Contoh: Selesaikan skripsi"></div><div class="field"><label>Area</label><input name="area" value="'+esc(g.area||'Academic')+'" placeholder="Academic"></div><div class="field"><label>Deadline</label><input name="deadline" type="date" value="'+(g.deadline||add(today(),30))+'"></div><div class="field"><label>Status</label><select name="status">'+['active','paused','completed'].map(s=>'<option value="'+s+'" '+(g.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select></div><div class="field"><label>Progress mode</label><select name="autoProgress"><option value="true" '+(g.autoProgress!==false?'selected':'')+'>Otomatis dari task + milestone</option><option value="false" '+(g.autoProgress===false?'selected':'')+'>Manual</option></select></div><div class="field"><label>Manual progress (%)</label><input name="progress" type="number" min="0" max="100" value="'+clamp(+g.progress||0,0,100)+'"></div><div class="field full"><label>Milestones — satu baris satu milestone</label><textarea name="milestones" rows="6" placeholder="Literature review\nMain theorem\nFinal revision">'+esc(ms)+'</textarea></div></div><input type="hidden" name="id" value="'+(g.id||'')+'"><button class="btn btn-primary" style="margin-top:14px">Simpan Goal</button></form>'}
function openGoal(g=null){open('<div class="modal-head"><div><div class="eyebrow">Goal</div><h2 id="modalTitle">'+(g?'Edit Goal':'Goal Baru')+'</h2></div><button class="icon-btn" data-act="close">×</button></div>'+goalForm(g||{}))}
function financeForm(x={}){return'<form id="financeForm"><div class="form-grid"><div class="field full"><label>Transaksi</label><input name="title" required value="'+esc(x.title||'')+'" placeholder="Contoh: Honor tutor / Makan siang"></div><div class="field"><label>Tipe</label><select name="type"><option value="income" '+(x.type==='income'?'selected':'')+'>Pemasukan</option><option value="expense" '+(x.type==='expense'?'selected':'')+'>Pengeluaran</option></select></div><div class="field"><label>Nominal</label><input name="amount" type="number" min="0" step="1000" required value="'+(+x.amount||'')+'"></div><div class="field"><label>Kategori</label><input name="category" value="'+esc(x.category||'General')+'" placeholder="Makanan, Transportasi, Pendidikan..."></div><div class="field"><label>Klasifikasi</label><select name="bucket">'+[['needs','Needs'],['wants','Wants'],['savings','Savings'],['investment','Investment']].map(v=>'<option value="'+v[0]+'" '+((x.bucket||'needs')===v[0]?'selected':'')+'>'+v[1]+'</option>').join('')+'</select></div><div class="field"><label>Tanggal</label><input name="date" type="date" value="'+(x.date||today())+'"></div><div class="field full"><label>Catatan</label><textarea name="notes" rows="2">'+esc(x.notes||'')+'</textarea></div></div><input type="hidden" name="id" value="'+(x.id||'')+'"><button class="btn btn-primary" style="margin-top:14px">Simpan Transaksi</button></form>'}
function budgetForm(x={}){return'<form id="budgetForm"><div class="form-grid"><div class="field"><label>Bulan</label><input name="month" type="month" value="'+esc(x.month||today().slice(0,7))+'"></div><div class="field"><label>Kategori</label><input name="category" required value="'+esc(x.category||'')+'" placeholder="Makanan"></div><div class="field full"><label>Batas budget</label><input name="limit" type="number" min="0" step="1000" required value="'+(+x.limit||'')+'"></div></div><input type="hidden" name="id" value="'+(x.id||'')+'"><button class="btn btn-primary" style="margin-top:14px">Simpan Budget</button></form>'}
function investmentForm(x={}){return'<form id="investmentForm"><div class="form-grid"><div class="field full"><label>Nama aset</label><input name="name" required value="'+esc(x.name||'')+'" placeholder="Contoh: IDX30 ETF / Emas"></div><div class="field"><label>Jenis</label><select name="type">'+['Saham','Reksa Dana','ETF','Emas','Obligasi','Crypto','Deposito','Lainnya'].map(v=>'<option '+(x.type===v?'selected':'')+'>'+v+'</option>').join('')+'</select></div><div class="field"><label>Jumlah unit</label><input name="units" type="number" min="0" step="0.000001" value="'+(+x.units||0)+'"></div><div class="field"><label>Harga beli rata-rata</label><input name="buyPrice" type="number" min="0" step="0.01" value="'+(+x.buyPrice||0)+'"></div><div class="field"><label>Harga sekarang</label><input name="currentPrice" type="number" min="0" step="0.01" value="'+(+x.currentPrice||0)+'"></div><div class="field"><label>Tanggal mulai</label><input name="date" type="date" value="'+(x.date||today())+'"></div><div class="field full"><label>Catatan</label><textarea name="notes" rows="3">'+esc(x.notes||'')+'</textarea></div></div><input type="hidden" name="id" value="'+(x.id||'')+'"><button class="btn btn-primary" style="margin-top:14px">Simpan Investasi</button></form>'}
function financeGoalForm(x={}){return'<form id="financeGoalForm"><div class="form-grid"><div class="field full"><label>Nama tujuan</label><input name="name" required value="'+esc(x.name||'')+'" placeholder="Dana darurat / Laptop / S2"></div><div class="field"><label>Target</label><input name="target" type="number" min="1" step="1000" required value="'+(+x.target||'')+'"></div><div class="field"><label>Terkumpul</label><input name="current" type="number" min="0" step="1000" value="'+(+x.current||0)+'"></div><div class="field full"><label>Target tanggal</label><input name="targetDate" type="date" value="'+(x.targetDate||'')+'"></div></div><input type="hidden" name="id" value="'+(x.id||'')+'"><button class="btn btn-primary" style="margin-top:14px">Simpan Financial Goal</button></form>'}
function openFinance(x=null){open('<div class="modal-head"><div><div class="eyebrow">FINANCE</div><h2 id="modalTitle">'+(x?'Edit Transaksi':'Transaksi Baru')+'</h2></div><button class="icon-btn" data-act="close">×</button></div>'+financeForm(x||{}))}
